INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64721537', 64721537, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'PUSAT PELAPORAN DAN ANALISIS TRANSAKSI KEUANGAN', 'Belanja Penjilidan - AS Keuangan', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 3500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', 'Penjilidan [10 eks x 2 keg]', '- Ruang lingkup: layanan percetakan dan penjilidan dokumen (cover & isi), termasuk pemotongan, penyusunan halaman, finishing, dan pengemasan sesuai pesanan. - Spesifikasi cetak: ukuran A4/F4 (sesuai permintaan), cetak hitam putih/warna sesuai file, kertas isi minimal HVS 70–80 gsm, cover minimal Art Carton 210–260 gsm (jika cover cetak), hasil tajam tidak buram/bleeding. - Spesifikasi jilid: pilihan lem panas/perfect binding, spiral, atau hardcover (sesuai permintaan), rapi, kuat, tidak mudah lepas; termasuk laminasi cover doff/glossy bila diminta. - Ketentuan mutu: halaman lengkap, urut, margin rapi, tidak terpotong, tidak terbalik; toleransi cacat 0 untuk eksemplar yang diserahkan (cacat wajib diganti). - Waktu layanan: proses sesuai tenggat yang disepakati, termasuk opsi antar ke lokasi; revisi/ulang cetak karena kesalahan produksi penyedia menjadi tanggung jawab penyedia.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1712229);
