INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64663057', 64663057, 'analyze_legacy', 'Kota Tangerang', 'kabkota', 'BADAN PENDAPATAN DAERAH', 'JASA KONSULTANSI PENGOLAHAN DATA PENDATAAN DAN PELAYANAN PBB-P2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Banten, Tangerang (Kota)', 77616000, 'April 2026', 'APBD', 0, 1, '1 orang x 4 bulan', 'Penugasan Tenaga Ahli pengolah data PBB-P2 untuk mempersiapkan kebutuhan-kebutuhan data dan pengolahan data terkait kegiatan Pendataan Verifikasi PBB-P2 tahun 2026 dan hasil pengajuan berkas Pelayanan PBB-P2 untuk di proses ke dalam aplikasi PBB-P2 dengan melihat potensi yang didapat untuk tahun berikutnya', '1. Mempersiapkan basis data atas objek PBB-P2 yang akan dilakukan kegiatan Verifikasi PBB-P2; 2. Mempersiapkan laporan kegiatan pendataan Verifikasi PBB-P2 berupa data yang telah dihasilkan dari kegiatan Verifikasi PBB-P2 tahun 2026; 3. Memproses hasil kegiatan Verifikasi Pendataan PBB-P2 yang telah ditagging oleh Surveyor Lapangan ke dalam sistem atau database SIMPBB-P2; 4. Memfilter data pelayanan yang telah masuk untuk dibandingkan dengan hasil kegiatan Verifikasi PBB-P2, agar tidak terjadi ketimpangan data terupdate antara kegiatan Verifikasi Pendataan PBB-P2 dengan pengajuan pelayanan tahun berjalan yang diajukan wajib pajak ke Bapenda; 5. Merekap output dari kegiatan Penyelesaian Pelayanan PBB-P2 di Bidang Pendataan, Verifikasi dan Pengolahan Data yang dapat dikelola dan menghasilkan informasi atas kegiatan pengerjaan penyelesaian permohonan pelayanan PBB-P2; 6. Menjalankan tugas lainnya dalam pengelolaan kegiatan pendataan dan Verifikasi PBB-P2.', 0, 